/**
 * Writes scripts/data/china-biotech-export-controls-pharma-deals-2026.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-china-biotech-export-cover.mjs.
 *
 *   node scripts/generate-china-biotech-export-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/china-biotech-export-controls-pharma-deals-2026.json');

export const IVONA_GUNJOVA_SANITY_ID = '5e67519a-1cdc-4b57-a881-29391db4accd';

/** Every blogPost field that applies to a healthcare-silo article. */
export const CHINA_BIOTECH_EXPORT_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-china-biotech-export-controls-pharma-deals-2026.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.CHINA_BIOTECH_EXPORT_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.CHINA_BIOTECH_EXPORT_EXECUTIVE_SUMMARY_HTML).split(/(?<=\.)\s+/)[0] ?? '';

  return {
    seo: {
      metaTitle: mod.CHINA_BIOTECH_EXPORT_META_TITLE,
      metaDescription: mod.CHINA_BIOTECH_EXPORT_META_DESCRIPTION,
      focusKeyword: 'China biotech export controls',
      keywords: [
        'China biotech export controls',
        'MOFCOM export catalogue',
        'China cell and gene therapy licensing',
        'siRNA China export',
        'China biotech BD',
        'Gulf market access China-origin assets',
        'China pharmaceutical licensing',
        'market access research',
      ],
      canonicalUrl: mod.CHINA_BIOTECH_EXPORT_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.CHINA_BIOTECH_EXPORT_META_TITLE,
      ogDescription: mod.CHINA_BIOTECH_EXPORT_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.CHINA_BIOTECH_EXPORT_COVER_IMAGE}`,
        alt: mod.CHINA_BIOTECH_EXPORT_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.CHINA_BIOTECH_EXPORT_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.CHINA_BIOTECH_EXPORT_SLUG },
    excerpt: mod.CHINA_BIOTECH_EXPORT_EXCERPT,
    publishedAt: mod.CHINA_BIOTECH_EXPORT_PUBLISHED_ISO,
    updatedAt: mod.CHINA_BIOTECH_EXPORT_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: IVONA_GUNJOVA_SANITY_ID,
      name: 'Ivona Gunjova',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.CHINA_BIOTECH_EXPORT_HERO_IMAGE}`,
      alt: mod.CHINA_BIOTECH_EXPORT_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for China biotech export controls',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.CHINA_BIOTECH_EXPORT_TAGS],
    country: 'China',
    language: 'en',
    readingTime: mod.CHINA_BIOTECH_EXPORT_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.CHINA_BIOTECH_EXPORT_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.CHINA_BIOTECH_EXPORT_EXECUTIVE_SUMMARY_HTML}\n\n${mod.CHINA_BIOTECH_EXPORT_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What a China biotech export controls brief should measure',
        type: 'table',
        data: JSON.stringify(
          mod.CHINA_BIOTECH_EXPORT_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'MOFCOM/MOST Announcement No. 48; Reuters; Fierce Biotech; China Daily; AstraZeneca Gracell releases',
      },
      portableText(
        firstParagraph ||
          'China biotech export controls became a live deal question on 16 October 2026.',
      ),
    ],
    faq: mod.CHINA_BIOTECH_EXPORT_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'car-t-saudi-arabia-market-research',
      'hematology-market-research-saudi-arabia',
      'nmpa-class-iii-registration-timeline-2026',
    ],
    ctaSection: { ...mod.CHINA_BIOTECH_EXPORT_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.CHINA_BIOTECH_EXPORT_BODY_HTML),
    factCheckedAt: mod.CHINA_BIOTECH_EXPORT_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/china-biotech-export-controls-pharma-deals-2026-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of CHINA_BIOTECH_EXPORT_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
